window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-20eb1fe8f676185a"]={"versions": [{"id": "FIG-20eb1fe8f676185a", "releases": ["R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Objekt- bzw. Instanzstrukturdiagramm (Deployment-Modell) im Kontext des AUTOSAR Adaptive Platform Manifests (Service Interface Deployment). Das Diagramm illustriert das Abflachen (Flattening) zusammengesetzter Datentypen eines <code>VariableDataPrototype</code> innerhalb eines signalbasierten Service-Deployments (<code>SignalBasedServiceInterfaceDeployment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Instanz <code>event1</code> vom Typ bzw. der Meta-Klasse <code>SignalBasedEvent</code> (SignalBasedEventDeployment). Dieses aggregiert über die Assoziation bzw. Rolle <code>eventElement</code> vier hierarchielose Unterelemente:</p>\n<ul class=\"fig-list\"><li><code>a</code>: Repräsentiert das primitive Element des übergeordneten Strukturtyps (<code>struct1.a</code>).\n</li><li><code>x</code>: Repräsentiert das erste primitive Feld der verschachtelten Struktur (<code>struct2.x</code>).\n</li><li><code>y</code>: Repräsentiert das zweite primitive Feld der verschachtelten Struktur (<code>struct2.y</code>).\n</li><li><code>z</code>: Repräsentiert das dritte primitive Feld der verschachtelten Struktur (<code>struct2.z</code>).\n</li></ul>\n<p class=\"fig-p\">Jedes dieser <code>eventElement</code>-Knoten bildet ein eigenständiges Blatt der aufgelösten Struktur ab.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Konfigurationsmodell zur Entwurfszeit. Es findet kein dynamischer Nachrichtenaustausch statt. Die dargestellte Baumstruktur beschreibt die Dekomposition: Ein ereignisbasiertes Datum (<code>event1</code>), dessen Nutzlast aus verschachtelten Strukturen besteht, wird für die signalbasierte Übertragung serialisierungsneutral in flache Einzelelemente (<code>a</code>, <code>x</code>, <code>y</code>, <code>z</code>) transformiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert die normative Vorgabe gemäß <code>[TPS_MANI_03121]</code>. Komplexe oder verschachtelte <code>VariableDataPrototype</code>-Strukturen innerhalb eines Events müssen über <code>eventElement</code>-Aggregationen in ihre primitiven Bestandteile zerlegt werden, damit diese in nachgelagerten Schritten individuellen <code>ISignal</code>s bzw. Signalen auf dem Kommunikationsmedium zugeordnet werden können.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7a816af1debd124f", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Objekt- bzw. Instanzstrukturdiagramm (Deployment-Modell) im Kontext des AUTOSAR Adaptive Platform Manifests (Service Interface Deployment). Das Diagramm illustriert das Abflachen (Flattening) zusammengesetzter Datentypen eines <code>VariableDataPrototype</code> innerhalb eines signalbasierten Service-Deployments (<code>SignalBasedServiceInterfaceDeployment</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Zentrales Element ist die Instanz <code>event1</code> vom Typ bzw. der Meta-Klasse <code>SignalBasedEvent</code> (SignalBasedEventDeployment). Dieses aggregiert über die Assoziation bzw. Rolle <code>eventElement</code> vier hierarchielose Unterelemente:</p>\n<ul class=\"fig-list\"><li><code>a</code>: Repräsentiert das primitive Element des übergeordneten Strukturtyps (<code>struct1.a</code>).\n</li><li><code>x</code>: Repräsentiert das erste primitive Feld der verschachtelten Struktur (<code>struct2.x</code>).\n</li><li><code>y</code>: Repräsentiert das zweite primitive Feld der verschachtelten Struktur (<code>struct2.y</code>).\n</li><li><code>z</code>: Repräsentiert das dritte primitive Feld der verschachtelten Struktur (<code>struct2.z</code>).\n</li></ul>\n<p class=\"fig-p\">Jedes dieser <code>eventElement</code>-Knoten bildet ein eigenständiges Blatt der aufgelösten Struktur ab.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Konfigurationsmodell zur Entwurfszeit. Es findet kein dynamischer Nachrichtenaustausch statt. Die dargestellte Baumstruktur beschreibt die Dekomposition: Ein ereignisbasiertes Datum (<code>event1</code>), dessen Nutzlast aus verschachtelten Strukturen besteht, wird für die signalbasierte Übertragung serialisierungsneutral in flache Einzelelemente (<code>a</code>, <code>x</code>, <code>y</code>, <code>z</code>) transformiert.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm visualisiert die normative Vorgabe gemäß <code>[TPS_MANI_03121]</code>. Komplexe oder verschachtelte <code>VariableDataPrototype</code>-Strukturen innerhalb eines Events müssen über <code>eventElement</code>-Aggregationen in ihre primitiven Bestandteile zerlegt werden, damit diese in nachgelagerten Schritten individuellen <code>ISignal</code>s bzw. Signalen auf dem Kommunikationsmedium zugeordnet werden können.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-20eb1fe8f676185a", "to": "FIG-7a816af1debd124f", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
